using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Directory.GetCurrentDirectory(), "evaluation-report");

        var storageFactory = DiskBasedReportingConfiguration.CreateStorageFactory(path);

        IEvaluator[] evaluators =
        [
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        ];

        return DiskBasedReportingConfiguration.Create(storageFactory, evaluators);
    }

    [TestMethod]
    public async Task Chat_responds_coherently()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                nameof(Chat_responds_coherently));

        IChatClient chatClient = scenario.GetChatConfiguration()!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_follows_instructions()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                nameof(Chat_follows_instructions));

        IChatClient chatClient = scenario.GetChatConfiguration()!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Always respond in one sentence."),
            new(ChatRole.User, "Explain what an evaluation harness is.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }
}

using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class IntegrationTests
{
    [TestMethod]
    public async Task AppHost_starts_and_chat_resource_is_available()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        await app.StartAsync();

        await app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(30));
    }
}

